import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"周易尚氏學 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"周易尚氏學 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"classics/shangshi/034.md","filePath":"classics/shangshi/034.md"}'),s={name:"classics/shangshi/034.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>歸藏曰革。李過曰。牢（上草）者勞也。以萬物勞於坎也。黃宗炎曰。物莫勞於牛。故從牛。按說文牢（上草）駁牛也。坤為牛。陽人坤中。色不純。故曰牢（上草）。而牛為物之最勞者。故取於駁牛。周易名坎。則取於陷險二義。上耳坎故曰習。羅汝懷雲。習當為折（左　）。禮玉藻帛為折（左　）。注衣有表裹而無著也。急就篇注。折（左　）謂重衣。皆重複之義。而折（左　）又假襲。禮錫襲。書卜不襲吉。故習當作襲。象曰。重險。象曰水洊至。即釋習坎之義。自注有便習之說。後儒多從之。夫諳練於行事。此事理之常。豈有諸練於行險者哉。按羅說是也。彖傳象傳。皆有明釋。王注及正義。詁為便習。此所以有野文之譏也孚。信也。有孚謂二五居中。遇陰。陽孚於上下陰也。舊解不知孚之故。在陽遇陰。故說皆不當。坎為心。亨通也。心亨亦謂二五。傳所謂剛中也。行有尚則專謂五。五往外得尊位。故曰有尚。曰有功。</p><p>彖曰。習坎。重險也。水流而不盈。行險而不失其信。維心亨。乃以剛中也。行有尚。往有功也。天險。不可升也。地險。山川丘陵也。王公設險以守其國。險之時用大矣哉。</p><p>水流若盈。則非坎矣。既曰坎則不盈也。坎為失。為信。陽居中。故不失其信。五天位。居坎中。故曰天險。艮止故不可升。二地位。居坎中。故曰地險。艮為山為丘陵。坎為川。故曰山川丘陵也。震為王公。艮為國。為守。為時。為天。</p><p>象曰。水洊至。習坎。君子以常德行。習教事。</p><p>洊。再也。重坎故曰再至。艮為君子。震為德行為言。故曰教。習則教不巳。而德行有常矣。</p><p>初六。習坎入於坎窞。兇。</p><p>說文焰（左無上穴）坎中更有坎。王肅雲。坎底也。字林雲。坎中小坎。一曰旁人。案王肅說是也。初居坎之最下。故人於坎底。</p><h3 id="象曰。習坎入坎。失道兇也。" tabindex="-1">象曰。習坎入坎。失道兇也。 <a class="header-anchor" href="#象曰。習坎入坎。失道兇也。" aria-label="Permalink to “象曰。習坎入坎。失道兇也。”">​</a></h3><p>震為大塗。故曰道。初於震無應。故曰失道兇。</p><p>九二。坎有險。求小得。</p><p>二失位。故有險。陰為小。二居中。孚於上下陰。故曰求小得。</p><h3 id="象曰。求小得。未出中也。" tabindex="-1">象曰。求小得。未出中也。 <a class="header-anchor" href="#象曰。求小得。未出中也。" aria-label="Permalink to “象曰。求小得。未出中也。”">​</a></h3><p>象曰未出中。言五無應。故曰未出。有應則上升五而當位。所得大矣。</p><p>六三。來之坎坎。檢從鄭向本且枕。入於坎窞。勿用。</p><p>三居上下坎之間。來內為坎。之外亦坎。故曰來之坎坎。孟子狗彘食人食而不知檢。趙歧雲檢斂也。又釋名雲。枕檢也。所以檢項也。然則枕與檢義同。檢且枕。仍承來之坎坎言。言內外俱受檢制。既檢且枕。仍與初交之人坎焰（左無上穴）同。夫前檢後枕。來往既陷於險境。其不能用也必矣。故曰勿用。</p><h3 id="象曰。來之坎坎。終無功也。" tabindex="-1">象曰。來之坎坎。終無功也。 <a class="header-anchor" href="#象曰。來之坎坎。終無功也。" aria-label="Permalink to “象曰。來之坎坎。終無功也。”">​</a></h3><p>勿用故曰無功。艮為枕。易林需之大壯雲。婚姻配合。同枕共牢。大壯通觀。以艮為枕。坤眾故同枕。</p><p>六四。樽酒。簋貳用嶽。納約自牖。終無咎。</p><p>坎為酒。震為尊。故曰尊酒。震為墓。簋祭器。以盛黍稷。中交正覆震。故曰簋貳。貳二同。曲禮雖不貳辭。注貳謂重骰（？）。此簋貳與損之二簋同。擊說文瓦器。簋貳用擊者。言用瓦簋。周禮施（右下瓦）人為簋。疏祭宗廟用木簋。今用瓦。祭天地尚質。器用陶匏。郊特牲亦云。器用陶匏。象天地之性。王夫之謂缶瓦也。與禮經合。得其義矣。約神約也。周禮秋官司約。掌六約。治神之約為上。治民之約次之。爻辭言尊簋。則祭神也。故知此約為神約。注神約命祀郊社群望及祖宗也。漢書高帝紀。約先人關者。注約要也。呂覽淫辭。秦趙相與約。注約盟也。艮為牖。震為言。故曰納約自牖。言詔明神而要誓。薦其盟祝之載辭於牖下也。又春官祖祝作盟祖之載辭。以敘國之信用。坎為信。故要誓於神也。承陽當位。故無咎。艮為終。故曰終無咎。酒擊牖咎為韻。</p><h3 id="象曰。樽酒簋貳。剛柔際也。" tabindex="-1">象曰。樽酒簋貳。剛柔際也。 <a class="header-anchor" href="#象曰。樽酒簋貳。剛柔際也。" aria-label="Permalink to “象曰。樽酒簋貳。剛柔際也。”">​</a></h3><p>四承陽故曰剛柔際。際說文會也。</p><p>九五。坎不盈。只既平。無咎。</p><p>坎不盈。義見前。只京虞作提（左　）。曰安也。鄭雲當作坻。小丘也。按易字不能定者。當定之以象。鄭於復卦無只侮。訓只為病。茲又訓為坻誠以坎不盈。與只既平為對文。則只為實字無疑。又五為艮主爻。艮山故曰抵。而坻與氏通。說文。氏巴蜀名山岸協之堆。旁者（上竹）欲落惰（左土？）者。曰氏。氏崩聲聞數百里。揚雄賦晌若氏貴（左阜）。而文選解嘲作坻貴（左阜）。應劭雲。天水有大　名曰隴坻。韋昭雲。低音若是理之是。是坻與氏通。俞樾雲。只既平。即氏貴（左阜）之氏。氏貴（左阜）即平矣。古本易蓋止作氏既乎。後人誤加示耳。案鄭詁為坻。蓋即疑只為氏。俞說正與鄭合。而韋昭音坻為是。由是證只坻提音皆由氏得。從氏者誤也。王引之謂鄭作宛在水中低之批為誤。豈知鄭並未作抵。坻毛傳雲小諸。釋水雲。小洲曰渚。茲曰小丘明非渚也。以鄭作低與解嘲同。與說文同也。不然鄭豈不知仍詁為病。使前後一律哉。坎為平。故曰抵既平。坎不盈為一事。坻既平又為一事。上下對文。詁只為安者固非。仍詁為病。於象雖合。於義未安也。</p><h3 id="象曰。坎不盈。中未光大也。" tabindex="-1">象曰。坎不盈。中未光大也。 <a class="header-anchor" href="#象曰。坎不盈。中未光大也。" aria-label="Permalink to “象曰。坎不盈。中未光大也。”">​</a></h3><p>陽陷陰中。雖得中而未光大。</p><p>系用徽纆，寘於叢棘，三歲不得，兇。</p><p>劉表雲。三股為徽。兩胎為墨（左絲）。皆索名。以繫縛罪人。虞翻雲徽墨黑索也。徽墨（左絲）之象。虞用卦變。以觀巽為繩。非也。蓋坎為矯揉（左車）。物之能矯揉（左車）者。莫過於繩。故以徽墨（左絲）取象。坎為棘。上坎下坎。故曰叢棘。真（上？）示通。周禮朝士鄭司農注及轂（左下禾）梁宣二年範寧注引。皆作示於叢棘。而詩鹿嗚示我周行。鄭則雲示當作真（上？）。真（上？）置也真（上？）於叢棘。舊解皆謂以黑索系罪人。置於獄。或議於九棘之下也。三歲不得。言三年不得出也。茹敦和雲。坎為三歲。</p><h3 id="象曰。上六失道。兇三歲也。" tabindex="-1">象曰。上六失道。兇三歲也。 <a class="header-anchor" href="#象曰。上六失道。兇三歲也。" aria-label="Permalink to “象曰。上六失道。兇三歲也。”">​</a></h3><p>上六應在三。三震為道。乃三不應上。故曰失道。</p><p>案上以叢棘為獄者。虞說也。虞謂獄外種棘。張惠言以不知所本而疑之矣。以周禮秋官朝士為本。使公卿議於九棘之下而定罪者。鄭說也。然不曰九棘。而曰叢棘。文王演易之時仍殷制。殷是否有三槐九棘之制不可知。則亦可疑也。況爻詞曰三歲不得。不得者不能遂其願也。象曰。上六失道。失道者。言所為不當也。不當故不得。於人獄詞意皆不合。按列子說符篇。臣有所與。共擔墨（左絲）薪菜者。曰九方皋。是徽墨（左絲）可以約薪菜。揚雄酒箴雲。子猶瓶矣。居井之湄。不得左右。牽於墨（左絲）徽。是徽墨（左絲）可為井索。胡為必束縛罪人。若以叢棘為疑。詩云。園有棘。其實之食。又云墓門有棘。斧以斯之。是棘常生於墓門及園囿。羽獵賦。斬叢棘。夷野草。吳志諸葛格（左　）傳。升山赴險。抵突叢棘。是叢棘常生於山林。安在必為獄。故易林需之坎雲。鑿井求玉。非卞氏寶。名因身辱。勞無所得。上二句謂所施不得地。釋真（上？）於叢棘。及失道之義也。下二句謂徒勞無功。釋真（上？）於業棘。三歲不得之義也。依易林此釋。似言徽墨（左絲）所以系物。然施於叢棘。則權權刺激。難於施設。故久不得。不得之故。則由於所真（上？）失道也。如是則不得與失道之故。與上文皆協洽矣。徽墨（左絲）皆繩索名耳。系物之用甚多。必謂專系罪人。無及執乎。</p>',31)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
